#!/usr/bin/env bash
# Copies the web atlas's third-party map and QR code libraries into site/vendor/ so visitors' browsers only ever
# load files from the atlas's own address. Run it only when deliberately upgrading a library, then commit the result.
#
#   bash scripts/vendor_web_libs.sh
#
# Versions are pinned here. The npm tarballs are checked against the registry's published integrity hash.
set -euo pipefail

MAPLIBRE=6.17.0
PMTILES=4.5.0
BASEMAPS=5.7.2
QRCODE=2.0.4
FFLATE=0.8.2 # used by pmtiles for decompression
# Fonts and sprites for the basemap style (OFL fonts, MIT-derived icons). Pinned to a commit for repeatability.
ASSETS_REF=${ASSETS_REF:-main}
ASSETS="https://raw.githubusercontent.com/protomaps/basemaps-assets/${ASSETS_REF}"

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
OUT="$ROOT/site/vendor"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

fetch_npm() { # name version -> extracts to $WORK/<safe name>
  local name="$1" version="$2" safe="${1//\//_}"
  (cd "$WORK" && npm pack "$name@$version" --silent >/dev/null)
  local tgz
  tgz="$(ls "$WORK" | grep -F "$(echo "${name#@}" | tr '/' '-')-$version.tgz")"
  local expected actual
  expected="$(npm view "$name@$version" dist.integrity)"
  actual="sha512-$(openssl dgst -sha512 -binary "$WORK/$tgz" | base64 -w0)"
  [ "$expected" = "$actual" ] || { echo "integrity mismatch for $name@$version" >&2; exit 1; }
  mkdir -p "$WORK/$safe" && tar xzf "$WORK/$tgz" -C "$WORK/$safe"
  echo "$WORK/$safe/package"
}

rm -rf "$OUT" && mkdir -p "$OUT"

p="$(fetch_npm maplibre-gl "$MAPLIBRE")"
mkdir -p "$OUT/maplibre-gl"
cp "$p/dist/maplibre-gl.mjs" "$p/dist/maplibre-gl-worker.mjs" "$p/dist/maplibre-gl.css" "$p/LICENSE.txt" "$OUT/maplibre-gl/"
# The bundles end with a pointer to a source map we do not ship; drop it so browsers do not request a missing file.
sed -i '/^\/\/# sourceMappingURL=/d' "$OUT/maplibre-gl/"*.mjs

p="$(fetch_npm pmtiles "$PMTILES")"
mkdir -p "$OUT/pmtiles" && cp "$p/dist/esm/index.js" "$OUT/pmtiles/pmtiles.mjs"
# Browsers cannot resolve the bare "fflate" import, so point it at the vendored copy.
sed -i 's#from"fflate"#from"../fflate/fflate.mjs"#; s#from "fflate"#from "../fflate/fflate.mjs"#' "$OUT/pmtiles/pmtiles.mjs"
grep -q 'fflate/fflate.mjs' "$OUT/pmtiles/pmtiles.mjs" || { echo "could not rewrite the fflate import" >&2; exit 1; }

p="$(fetch_npm fflate "$FFLATE")"
mkdir -p "$OUT/fflate" && cp "$p/esm/browser.js" "$OUT/fflate/fflate.mjs" && cp "$p/LICENSE" "$OUT/fflate/LICENSE"

p="$(fetch_npm @protomaps/basemaps "$BASEMAPS")"
mkdir -p "$OUT/protomaps-basemaps" && cp "$p/dist/esm/index.js" "$OUT/protomaps-basemaps/basemaps.mjs"

p="$(fetch_npm qrcode-generator "$QRCODE")"
mkdir -p "$OUT/qrcode-generator" && cp "$p/dist/qrcode.mjs" "$OUT/qrcode-generator/qrcode.mjs"
sed -i '/^\/\/# sourceMappingURL=/d' "$OUT"/*/*.mjs

# Basemap fonts: only the Latin ranges the English labels need (basic Latin, Latin extended, punctuation).
for font in "Noto Sans Regular" "Noto Sans Medium" "Noto Sans Italic"; do
  mkdir -p "$OUT/basemap-assets/fonts/$font"
  for range in 0-255 256-511 8192-8447; do
    curl -fsS "$ASSETS/fonts/${font// /%20}/$range.pbf" -o "$OUT/basemap-assets/fonts/$font/$range.pbf"
  done
done
curl -fsS "$ASSETS/fonts/OFL.txt" -o "$OUT/basemap-assets/fonts/OFL.txt"
mkdir -p "$OUT/basemap-assets/sprites"
for f in dark.json dark.png dark@2x.json dark@2x.png; do
  curl -fsS "$ASSETS/sprites/v4/$f" -o "$OUT/basemap-assets/sprites/$f"
done

{
  echo "# Vendored libraries"
  echo
  echo "Generated by scripts/vendor_web_libs.sh. Do not edit these files by hand."
  echo
  echo "| Library | Version | License |"
  echo "| :-- | :-- | :-- |"
  echo "| maplibre-gl | $MAPLIBRE | BSD-3-Clause |"
  echo "| pmtiles | $PMTILES | BSD-3-Clause |"
  echo "| @protomaps/basemaps | $BASEMAPS | BSD-3-Clause |"
  echo "| qrcode-generator | $QRCODE | MIT |"
  echo "| fflate | $FFLATE | MIT |"
  echo "| protomaps/basemaps-assets fonts | $ASSETS_REF | SIL OFL 1.1 |"
  echo "| protomaps/basemaps-assets sprites | $ASSETS_REF | MIT (tangrams/icons) |"
  echo
  echo "## SHA-256"
  echo
  echo '```'
  (cd "$OUT" && find . -type f ! -name VENDORED.md -print0 | LC_ALL=C sort -z | xargs -0 sha256sum)
  echo '```'
} > "$OUT/VENDORED.md"
echo "Vendored into $OUT"
